const body = $json.body ?? $json;
const required = ['source','generated_at','host','git_head','state','fresh_rows','fresh_setup_events','matured_setup_events','per_block_matured','economic_outcomes','promotion'];
for (const key of required) { if (!(key in body)) throw new Error(`missing_${key}`); }
if (body.source !== 'goldmicro-v5-prospective') throw new Error('source_not_allowed');
if (body.economic_outcomes !== 'HIDDEN / NOT EVALUATED') throw new Error('economic_outcomes_must_remain_hidden');
if (body.promotion !== 'DISABLED') throw new Error('promotion_must_remain_disabled');
if (!Array.isArray(body.per_block_matured) || body.per_block_matured.length !== 5) throw new Error('invalid_block_counts');
for (const k of ['fresh_rows','fresh_setup_events','matured_setup_events']) { if (!Number.isInteger(body[k]) || body[k] < 0) throw new Error(`invalid_${k}`); }
for (const n of body.per_block_matured) { if (!Number.isInteger(n) || n < 0) throw new Error('invalid_block_count'); }
return [{ json: { accepted: true, received_at: new Date().toISOString(), status: body } }];
